{
  "decisions": [
    {
      "entity_path": "config/archive_format",
      "change_type": "reject",
      "reasoning": "We rejected zstd because the downstream importer cannot decode it. The importer accepts zip and gzip. Use gzip for the smallest compatible export until the importer gains zstd support.",
      "constraint": "Nightly archives must be decodable by the downstream importer.",
      "stale_when": "Downstream importer adds tested zstd support."
    }
  ],
  "note": "This file is independent of any connected memory server."
}

{
  "status": "applied",
  "key": "archive_format",
  "value": "zstd",
  "rationale": "zstd produces the smallest archives at 6 MB, versus 9 MB for gzip and 12 MB for zip. The prior decision record rejected zstd solely because the downstream importer lacked decode support, but it explicitly marked itself stale once the importer gained tested zstd support. Current evidence confirms the importer was upgraded today and its zstd decode compatibility test now passes alongside zip and gzip. All three formats are supported; zstd is the smallest."
}
